  Binary(node: any, parent: any): boolean {
  if (
    node.operator === "**" &&
    isBinaryExpression(parent, { operator: "**" })
  ) {
    return parent.left === node;
  }

  if (this.isClassExtendsClause(node, parent)) {
    return true;
  }

  if (
    this.hasPostfixPart(node, parent) ||
    isUnaryLike(parent) ||
    isAwaitExpression(parent)
